#!/usr/bin/env python3
import os, sys, subprocess, re, shutil, textwrap
from dataclasses import dataclass

VERSION = "git-graph 0.7.0"
MODELS = ["git-flow", "simple", "none"]

SHORT_HELP = """Structured Git graphs for your branching model.
    https://github.com/mlange-42/git-graph

EXAMPES:
    git-graph                   -> Show graph
    git-graph --style round     -> Show graph in a different style
    git-graph --model <model>   -> Show graph using a certain <model>
    git-graph model --list      -> List available branching models
    git-graph model             -> Show repo's current branching models
    git-graph model <model>     -> Permanently set model <model> for this repo

Usage: executable [OPTIONS] [COMMAND]

Commands:
  model  Prints or permanently sets the branching model for a repository.
  help   Print this message or the help of the given subcommand(s)

Options:
  -p, --path <path>                 Open repository from this path or above. Default '.'
      --skip-repo-owner-validation  Skip owner validation for the repository.
                                    This will turn off libgit2's owner validation, which may increase security risks.
                                    Please do not disable this validation for repositories you do not trust.
  -m, --model <model>               Branching model. Available presets are [simple|git-flow|none].
                                    Default: git-flow. 
                                    Permanently set the model for a repository with
                                    > git-graph model <model>
  -n, --max-count <n>               Maximum number of commits
      --color <color>               Specify when colors should be used. One of [auto|always|never].
                                    Default: auto.
      --no-color                    Print without colors. Missing color support should be detected
                                    automatically (e.g. when piping to a file).
                                    Overrides option '--color'
  -w, --wrap [<wrap>...]            Line wrapping for formatted commit text. Default: 'auto 0 8'
                                    Argument format: [<width>|auto|none[ <indent1>[ <indent2>]]]
                                    For examples, consult 'git-graph --help'
  -f, --format <format>             Commit format. One of [oneline|short|medium|full|"<string>"].
                                      (First character can be used as abbreviation, e.g. '-f m')
                                    Default: oneline.
                                    For placeholders supported in "<string>", consult 'git-graph --help'
  -r, --reverse                     Reverse the order of commits.
  -l, --local                       Show only local branches, no remotes.
      --svg                         Render graph as SVG instead of text-based.
  -d, --debug                       Additional debug output and graphics.
  -S, --sparse                      Print a less compact graph: merge lines point to target lines
                                    rather than merge commits.
  -s, --style <style>               Output style. One of [normal/thin|round|bold|double|ascii].
                                      (First character can be used as abbreviation, e.g. '-s r')
  -h, --help                        Print help (see more with '--help')
  -V, --version                     Print version
"""

LONG_HELP = SHORT_HELP.replace("  -p, --path <path>                 Open repository from this path or above. Default '.'", "  -p, --path <path>\n          Open repository from this path or above. Default '.'")
MODEL_HELP = """Prints or permanently sets the branching model for a repository.

Usage: executable model [OPTIONS] [model]

Arguments:
  [model]  The branching model to be used. Available presets are [simple|git-flow|none].
           When not given, prints the currently set model.

Options:
  -l, --list  List all available branching models.
  -h, --help  Print help
"""

@dataclass
class Opts:
    path: str = "."
    model: str = None
    max_count: int = None
    color: str = "auto"
    no_color: bool = False
    wrap: tuple = None  # (width or None, indent1, indent2), width None means no wrap
    fmt: str = "oneline"
    reverse: bool = False
    local: bool = False
    svg: bool = False
    debug: bool = False
    sparse: bool = False
    style: str = "normal"
    subcmd: str = None
    subargs: list = None

class GitError(Exception): pass

def run_git(repo, args, check=True):
    p = subprocess.run(["git", "-C", repo] + args, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if check and p.returncode != 0:
        raise GitError(p.stderr.strip() or p.stdout.strip())
    return p

def resolve_repo(path):
    if not os.path.exists(path):
        print(f"ERROR: failed to resolve path '{path}': No such file or directory", file=sys.stderr)
        print("       Navigate into a repository before running git-graph, or use option --path", file=sys.stderr)
        sys.exit(1)
    p = subprocess.run(["git", "-C", path, "rev-parse", "--show-toplevel"], text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if p.returncode != 0:
        print(f"ERROR: could not find repository at '{path}'", file=sys.stderr)
        print("       Navigate into a repository before running git-graph, or use option --path", file=sys.stderr)
        sys.exit(1)
    return p.stdout.strip()

def err_arg(msg):
    print(f"error: {msg}\n", file=sys.stderr)
    print("Usage: executable [OPTIONS] [COMMAND]\n", file=sys.stderr)
    print("For more information, try '--help'.", file=sys.stderr)
    sys.exit(2)

def parse_args(argv):
    opts = Opts()
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "help":
            if i+1 < len(argv) and argv[i+1] == "model":
                print(MODEL_HELP, end=""); sys.exit(0)
            print(SHORT_HELP, end=""); sys.exit(0)
        if a == "model":
            opts.subcmd = "model"; opts.subargs = argv[i+1:]; return opts
        if a in ("-h", "--help"):
            print(SHORT_HELP if a == "-h" else SHORT_HELP, end=""); sys.exit(0)
        if a in ("-V", "--version"):
            print(VERSION); sys.exit(0)
        if a in ("-p", "--path"):
            i += 1
            if i >= len(argv): err_arg("a value is required for '--path <path>'")
            opts.path = argv[i]
        elif a == "--skip-repo-owner-validation":
            pass
        elif a in ("-m", "--model"):
            i += 1
            if i >= len(argv): err_arg("a value is required for '--model <model>'")
            opts.model = argv[i]
        elif a in ("-n", "--max-count"):
            i += 1
            if i >= len(argv): err_arg("a value is required for '--max-count <n>'")
            try:
                n = int(argv[i])
                if n <= 0: raise ValueError
                opts.max_count = n
            except ValueError:
                print(f"Option max-count must be a positive number, but got '{argv[i]}'", file=sys.stderr); sys.exit(1)
        elif a == "--color":
            i += 1
            if i >= len(argv): err_arg("a value is required for '--color <color>'")
            if argv[i] not in ("auto", "always", "never"):
                print(f"Unknown color mode '{argv[i]}'. Supports [auto|always|never].", file=sys.stderr); sys.exit(1)
            opts.color = argv[i]
        elif a == "--no-color": opts.no_color = True
        elif a in ("-w", "--wrap"):
            vals=[]; j=i+1
            while j < len(argv) and not argv[j].startswith('-') and argv[j] not in ("model","help"):
                vals.append(argv[j]); j+=1
            i = j-1
            opts.wrap = parse_wrap(vals)
        elif a in ("-f", "--format"):
            i += 1
            if i >= len(argv): err_arg("a value is required for '--format <format>'")
            opts.fmt = argv[i]
        elif a in ("-r", "--reverse"): opts.reverse = True
        elif a in ("-l", "--local"): opts.local = True
        elif a == "--svg": opts.svg = True
        elif a in ("-d", "--debug"): opts.debug = True
        elif a in ("-S", "--sparse"): opts.sparse = True
        elif a in ("-s", "--style"):
            i += 1
            if i >= len(argv): err_arg("a value is required for '--style <style>'")
            opts.style = normalize_style(argv[i])
        elif a.startswith('-'):
            err_arg(f"unexpected argument '{a}' found")
        else:
            err_arg(f"unexpected argument '{a}' found")
        i += 1
    return opts

def parse_wrap(vals):
    if not vals:
        return (None,0,8)
    mode = vals[0]
    if mode in ("none", "auto"):
        width = None
    else:
        try: width = int(mode)
        except ValueError:
            print(f"ERROR: Can't parse option --wrap '{mode}' to integers.", file=sys.stderr); sys.exit(1)
    ind1, ind2 = 0, 8
    if len(vals) > 1:
        try: ind1 = int(vals[1])
        except ValueError:
            print(f"ERROR: Can't parse option --wrap '{' '.join(vals)}' to integers.", file=sys.stderr); sys.exit(1)
    if len(vals) > 2:
        try: ind2 = int(vals[2])
        except ValueError:
            print(f"ERROR: Can't parse option --wrap '{' '.join(vals)}' to integers.", file=sys.stderr); sys.exit(1)
    return (width, ind1, ind2)

def normalize_style(s):
    m = {"normal":"normal","thin":"normal","round":"round","bold":"bold","double":"double","ascii":"ascii",
         "n":"normal","t":"normal","r":"round","b":"bold","d":"double","a":"ascii"}
    if s not in m:
        print(f"Unknown characters/style '{s}'. Must be one of [normal|thin|round|bold|double|ascii]", file=sys.stderr); sys.exit(1)
    return m[s]

def check_model(name):
    if name and name not in MODELS:
        home = os.path.expanduser("~")
        print(f"ERROR: No branching model named '{name}' found in {home}/.config/git-graph/models", file=sys.stderr)
        print("       Available models are: git-flow, simple, none", file=sys.stderr)
        sys.exit(1)

def handle_model(opts):
    args = opts.subargs or []
    if any(a in ("-h", "--help") for a in args): print(MODEL_HELP, end=""); return
    if any(a in ("-l", "--list") for a in args):
        print("\n".join(MODELS)); return
    model = next((a for a in args if not a.startswith('-')), None)
    repo = resolve_repo(opts.path)
    cfg = os.path.join(repo, ".git", "git-graph.toml")
    if model is None:
        if os.path.exists(cfg):
            txt = open(cfg).read(); mm = re.search(r'model\s*=\s*"([^"]+)"', txt)
            if mm: print(mm.group(1), end=""); return
        print("No branching model set", end=""); return
    check_model(model)
    os.makedirs(os.path.dirname(cfg), exist_ok=True)
    with open(cfg,"w") as f: f.write(f'model = "{model}"\n')
    print(f"Branching model set to '{model}'", file=sys.stderr)

STYLE = {
 'ascii': dict(bullet='*', merge='o', vert='|', open='.', close="'", horiz='-', tee='|'),
 'normal': dict(bullet='●', merge='○', vert='│', open='┐', close='┘', horiz='─', tee='├'),
 'round': dict(bullet='●', merge='○', vert='│', open='╮', close='╯', horiz='─', tee='├'),
 'bold': dict(bullet='●', merge='○', vert='┃', open='┓', close='┛', horiz='━', tee='┣'),
 'double': dict(bullet='●', merge='○', vert='║', open='╗', close='╝', horiz='═', tee='╠'),
}

def ref_info(repo, include_remotes=True):
    refs_by_hash = {}
    def add(h, kind, name): refs_by_hash.setdefault(h, {"branches":[],"tags":[]})[kind].append(name)
    p = run_git(repo, ["for-each-ref", "--format=%(objectname) %(refname)", "refs/heads", "refs/tags"] + (["refs/remotes"] if include_remotes else []), check=False)
    for line in p.stdout.splitlines():
        if not line: continue
        h, ref = line.split(' ',1)
        if ref.startswith('refs/heads/'):
            add(h,"branches",ref[len('refs/heads/'):])
        elif ref.startswith('refs/remotes/'):
            nm = ref[len('refs/remotes/'):]
            if nm.endswith('/HEAD'): continue
            add(h,"branches",nm)
        elif ref.startswith('refs/tags/'):
            add(h,"tags",ref[len('refs/tags/'):])
    hp = run_git(repo, ["rev-parse", "HEAD"], check=False)
    head_hash = hp.stdout.strip() if hp.returncode == 0 else None
    bp = run_git(repo, ["symbolic-ref", "-q", "--short", "HEAD"], check=False)
    head_branch = bp.stdout.strip() if bp.returncode == 0 else None
    native = {}
    cp = run_git(repo, ["log", "--all", "--format=%H"], check=False)
    hashes = set(cp.stdout.split()) | set(refs_by_hash.keys())
    for h in hashes:
        nd = run_git(repo, ["log", "-1", "--format=%d", "--decorate=short", h], check=False).stdout.strip('\n')
        native[h] = nd
    custom = {}
    for h in hashes:
        info = refs_by_hash.get(h, {"branches":[],"tags":[]})
        branches = sorted(info["branches"])
        tags = sorted(info["tags"])
        parts=[]
        if head_branch and h == head_hash and head_branch in branches:
            parts.append(f"HEAD -> {head_branch}"); branches.remove(head_branch)
        elif (not head_branch) and h == head_hash:
            if branches:
                b=branches.pop(0); parts.append(f"HEAD -> ({b})")
            else:
                parts.append("HEAD")
        parts += branches
        s=""
        if parts: s += " (" + ", ".join(parts) + ")"
        if tags: s += " [" + ", ".join(tags) + "]"
        custom[h]=s
    return native, custom

def commit_parents(repo):
    p = run_git(repo, ["log", "--all", "--format=%H %P"], check=False)
    d={}
    for line in p.stdout.splitlines():
        sp=line.split();
        if sp: d[sp[0]]=sp[1:]
    return d

MARK='\x1e'; SEP='\x1f'

def preset_name(fmt):
    low=fmt.lower()
    mapping={'o':'oneline','oneline':'oneline','s':'short','short':'short','m':'medium','medium':'medium','f':'full','full':'full'}
    return mapping.get(low)

def escape_custom_for_git(fmt):
    # Preserve git-graph's narrower placeholder set: unsupported percent escapes are literal.
    allowed1=set('HhPpdsbB')
    allowed2={'an','ae','ad','as','ar','cn','ce','cd','cs','cr'}
    out=[]; i=0
    while i < len(fmt):
        c=fmt[i]
        if c == '\n':
            out.append('%n' + '%x1e%H%x1f'); i+=1; continue
        if c != '%': out.append(c); i+=1; continue
        # literal %% remains two percent signs in git-graph
        if i+1 < len(fmt) and fmt[i+1] == '%':
            out.append('%%%%'); i+=2; continue
        j=i+1; mod=''
        if j < len(fmt) and fmt[j] in '+- ':
            mod=fmt[j]; j+=1
        if j < len(fmt) and fmt[j] == 'n':
            out.append('%'+mod+'n' + '%x1e%H%x1f'); i=j+1; continue
        if j < len(fmt) and fmt[j] in allowed1:
            out.append('%'+mod+fmt[j]); i=j+1; continue
        if j+1 < len(fmt) and fmt[j:j+2] in allowed2:
            out.append('%'+mod+fmt[j:j+2]); i=j+2; continue
        # unknown escape: make percent literal for git
        out.append('%%')
        i += 1
    return ''.join(out)

def make_git_format(fmt):
    pn=preset_name(fmt)
    if pn == 'oneline': raw='%h%d %s'
    elif pn in ('short','medium','full'): return pn, True
    else: raw=fmt
    return (MARK + '%H' + SEP + escape_custom_for_git(raw), False)

def build_log(repo, opts):
    # empty repository: mimic libgit2-ish error observed for default branch repos
    hp = run_git(repo, ["rev-parse", "--verify", "HEAD"], check=False)
    if hp.returncode != 0:
        print("reference 'refs/heads/master' not found", file=sys.stderr); sys.exit(1)
    fmt, native_preset = make_git_format(opts.fmt)
    cmd = ["log", "--graph", "--date-order", "--decorate=short"]
    if opts.max_count: cmd += [f"--max-count={opts.max_count}"]
    if opts.local: cmd += ["--branches", "--tags"]
    else: cmd += ["--all"]
    if native_preset:
        cmd += [f"--format={fmt}"]
    else:
        cmd += [f"--format={fmt}"]
    p=run_git(repo, cmd, check=False)
    if p.returncode != 0:
        print(p.stderr.strip(), file=sys.stderr); sys.exit(1)
    return p.stdout.splitlines()

@dataclass
class Line:
    prefix: str
    text: str
    h: str = None
    commit: bool = False
    graph_only: bool = False

def split_lines(raw_lines, native_deco, custom_deco, parents, preset=False):
    res=[]; cur=None
    for line in raw_lines:
        h=None; commit=False
        if MARK in line:
            pre, rest = line.split(MARK,1)
            if SEP in rest:
                h, text = rest.split(SEP,1); cur=h
            else: text=rest
            commit = h is not None and re.search(r'\*', pre) is not None
        else:
            # heuristic split for native presets
            if not line:
                pre=''; text=''
            else:
                m = re.search(r'[^ |/\\*]', line)
                if m:
                    first=m.start()
                    token=line[first:]
                    if token.startswith(('commit ', 'Merge:', 'Author:', 'Date:', 'Commit:')):
                        plen=first
                    else:
                        plen=max(0, first-4)  # preset message/body indentation
                    pre=line[:plen]; text=line[plen:]
                else:
                    pre=line; text=''
            if text.startswith('commit '):
                mm=re.match(r'commit ([0-9a-fA-F]+)', text)
                if mm:
                    full=mm.group(1); h=full; cur=full; commit=True
        if h is None: h=cur
        if h and h in native_deco and native_deco[h]:
            text = text.replace(native_deco[h], custom_deco.get(h,''))
        res.append(Line(pre,text,h,commit, text==''))
    return res

def transform_prefix(prefix, st, maxlen, is_commit=False, is_merge=False, compress=False, has_text=False, sparse=False):
    chars=list(prefix)
    out=[' ']*max(len(chars)+2, maxlen+2)]
    for i,ch in enumerate(chars):
        if ch=='|': out[i]=st['vert']
        elif ch=='*': out[i]=st['merge'] if is_merge else st['bullet']
        elif ch=='/': out[i]='/'
        elif ch=='\\': out[i]='\\'
        else: out[i]=' '
    if is_commit and compress:
        try: k=chars.index('*')
        except ValueError: k=-1
        if k>=0:
            out[k]=st['merge']
            if k+1 >= len(out): out.extend(' '*(k+2-len(out)))
            out[k+1]='<'
            if k+2 >= len(out): out.extend(' '*(k+3-len(out)))
            out[k+2]=st['open']
    # process slashes/backslashes (unless already consumed on compressed commit)
    if not (is_commit and compress):
        for i,ch in enumerate(chars):
            if ch=='/':
                if i>0 and out[i-1] == st['vert']:
                    out[i-1]=st['tee']
                out[i]=st['horiz']
                if i+1 >= len(out): out.append(' ')
                out[i+1]=st['close']
            elif ch=='\\':
                if sparse or not has_text:
                    out[i]='<'
                    if i+1 >= len(out): out.append(' ')
                    out[i+1]=st['open']
                else:
                    # after a compressed merge, Git prints the diagonal on the first
                    # continuation line; git-graph shows the post-merge vertical column.
                    out[i]=' '
                    if i+1 >= len(out): out.append(' ')
                    out[i+1]=st['vert']
    body=''.join(out).rstrip()
    return ' ' + body.ljust(maxlen+1)

def transform(lines, opts, parents):
    st=STYLE[opts.style]
    max_native=0
    for ln in lines:
        max_native=max(max_native, len(ln.prefix))
    out=[]
    prev_was_compressed_merge=False
    for idx,ln in enumerate(lines):
        is_merge = bool(ln.h and len(parents.get(ln.h,[]))>1)
        compress = (not opts.sparse) and ln.commit and is_merge
        # skip graph-only diagonal immediately after a compressed one-line merge
        if (not opts.sparse) and ln.graph_only and '\\' in ln.prefix and prev_was_compressed_merge:
            prev_was_compressed_merge=False
            continue
        pref=transform_prefix(ln.prefix, st, max_native, ln.commit, is_merge, compress, bool(ln.text), opts.sparse)
        out.append((pref, ln.text, ln.commit))
        prev_was_compressed_merge = compress
        if ln.text:
            prev_was_compressed_merge = compress
    return out

def apply_wrap(lines, wrap):
    if not wrap or wrap[0] is None: return [p+t for p,t,c in lines]
    width, ind1, ind2 = wrap
    res=[]
    for pref,text,commit in lines:
        p1=pref + (' '*ind1)
        if not text:
            res.append(p1.rstrip() if ind1 else pref.rstrip())
            continue
        avail=max(10, width-len(p1))
        chunks=textwrap.wrap(text, width=avail, replace_whitespace=False, drop_whitespace=True) or ['']
        res.append(p1+chunks[0])
        cont=(' '*len(pref)) + (' '*ind2)
        avail2=max(10, width-len(cont))
        rest=' '.join(chunks[1:])
        # wrap remaining text using continuation width; previous wrapping may differ, rewrap tail
        if len(chunks)>1:
            tail=text[len(chunks[0]):].lstrip()
            for c in textwrap.wrap(tail, width=avail2, replace_whitespace=False, drop_whitespace=True):
                res.append(cont+c)
    return res

def colorize(lines, opts, repo, custom_deco):
    use = (opts.color == 'always' and not opts.no_color)
    if not use: return lines
    yellow='\x1b[38;5;11m'; reset='\x1b[0m'
    # minimal coloring: graph/hash yellow-ish. Good enough for terminals; exact branch coloring is elaborate.
    res=[]
    for line in lines:
        m=re.search(r'([0-9a-f]{7,40})', line)
        if m:
            line=line[:m.start()] + yellow + m.group(1) + reset + line[m.end():]
        res.append(line)
    return res

def render_svg(repo, opts, parents):
    # Simple SVG compatible with the observed linear output; text is intentionally omitted by upstream too.
    commits = run_git(repo, ["log", "--all", "--format=%H"], check=False).stdout.splitlines()
    if opts.max_count: commits=commits[:opts.max_count]
    h=max(30, 15*(len(commits)+2)); y=[15+i*15 for i in range(len(commits))]
    print(f'<svg height="{h}" viewBox="0 0 30 {h}" width="30" xmlns="http://www.w3.org/2000/svg">')
    if len(y)>1: print(f'<line stroke="blue" stroke-width="1" x1="15" x2="15" y1="{y[0]}" y2="{y[-1]}"/>')
    for yy in y: print(f'<circle cx="15" cy="{yy}" fill="blue" r="4" stroke="blue" stroke-width="1"/>')
    print('</svg>')

def main(argv):
    opts=parse_args(argv)
    if opts.subcmd == 'model': handle_model(opts); return
    check_model(opts.model)
    repo=resolve_repo(opts.path)
    parents=commit_parents(repo)
    if opts.svg:
        render_svg(repo, opts, parents); return
    raw=build_log(repo, opts)
    if not raw:
        print("reference 'refs/heads/master' not found", file=sys.stderr); sys.exit(1)
    native_deco, custom_deco=ref_info(repo, not opts.local)
    preset = preset_name(opts.fmt) in ('short','medium','full')
    parsed=split_lines(raw, native_deco, custom_deco, parents, preset)
    transformed=transform(parsed, opts, parents)
    output=apply_wrap(transformed, opts.wrap)
    output=colorize(output, opts, repo, custom_deco)
    if opts.reverse:
        output=list(reversed(output))
    sys.stdout.write('\n'.join(output))
    if output: sys.stdout.write('\n')

if __name__ == '__main__':
    main(sys.argv[1:])
